import React from 'react';

import { IHikingJointlyEquipment } from '@apps/Hiking/@types/hikingJointlyEquipment.types';
import PohCard from '@ui-kit/Card';

import nophotoImg from '../../../../img/nophoto.png';
import tentImg from '../../../../img/tent.jpeg';

interface IHikingJointlyEquipmentCardProps {
  jointlyEquipment: IHikingJointlyEquipment;
  toolbar?: React.ReactNode;
  children?: React.ReactNode;
}

const HikingJointlyEquipmentCard = ({
  jointlyEquipment,
  toolbar,
  children,
}: IHikingJointlyEquipmentCardProps) => {
  return (
    <PohCard
      img={
        jointlyEquipment.equip?.photo || (jointlyEquipment.type == 'tent' ? tentImg : nophotoImg)
      }
      header={
        <span className="d-flex justify-conjointlyEquipment-between align-items-center">
          {jointlyEquipment.name}
          <small
            title={[
              'Вместимость',
              `Комфорт: ${jointlyEquipment.capacity}`,
              `Максимум: ${jointlyEquipment.capacity_max}`,
            ].join('\n')}
          >
            🧍
            <sub className="text-success">{jointlyEquipment.capacity}</sub>{' '}
            <sup className="text-danger">{jointlyEquipment.capacity_max}</sup>
          </small>
        </span>
      }
      footer={toolbar}
      bodyClassName="p-0"
    >
      <div className="p-3 py-1 border-bottom bg-light">
        <em>{jointlyEquipment.comment}</em>
      </div>
      {children}
    </PohCard>
  );
};

export default HikingJointlyEquipmentCard;
