import React, { FormEvent } from 'react';

import { selectOneEquipItemInModal } from '@apps/Equip/components/SelectOneEquipModal';
import { getHikingJointlyEquipmentNameByType } from '@apps/Hiking/@helpers/jointlyEquipment.helper';
import { IHikingJointlyEquipment } from '@apps/Hiking/@types/hikingJointlyEquipment.types';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { showModal } from '@ui-kit/Modal';

interface IHikingJointlyEquipmentFormProps {
  jointlyEquipment: IHikingJointlyEquipment;
  onSave: (t: IHikingJointlyEquipment) => void;
}

const HikingJointlyEquipmentForm = ({
  jointlyEquipment,
  onSave,
}: IHikingJointlyEquipmentFormProps) => {
  const [modelData, setModelData] = React.useState<IHikingJointlyEquipment>(jointlyEquipment);
  const onSubmit = (e: FormEvent) => {
    e.preventDefault();
    onSave(modelData);
  };

  function handleChange<k extends keyof IHikingJointlyEquipment>(fieldName: k) {
    return (value: IHikingJointlyEquipment[k]) =>
      setModelData({ ...modelData, [fieldName]: value });
  }

  return (
    <form onSubmit={onSubmit} className="d-flex flex-column" style={{ gap: 12, minWidth: '40vw' }}>
      <PohRow>
        <PohCol sm={2}>Снаряжение</PohCol>
        <PohCol sm={10} className="d-flex align-items-end">
          <PohInput
            placeholder="Выбрать из Снаряжения"
            defaultValue={modelData.equip?.name ?? ''}
            readOnly
            wrapperClassName="flex-grow-1"
            required
            onClick={async () => {
              const selectedEquip = await selectOneEquipItemInModal({});
              setModelData((cur) => ({
                ...cur,
                equip: selectedEquip,
                name: cur.name || selectedEquip.name,
              }));
            }}
          />
          <PohButton icon={IconsEnum.close} onClick={() => handleChange('equip')(null)} />
        </PohCol>
      </PohRow>
      <PohInput
        horizontal
        label="Название"
        value={modelData.name}
        onChange={handleChange('name')}
        required
      />

      <PohRow>
        <PohCol sm={2} />
        <PohCol sm={4}>
          <PohInput
            label="Вместимость (комфорт)"
            type={InputTypes.number}
            value={modelData.capacity ? modelData.capacity.toString() : ''}
            onChange={(v) => handleChange('capacity')(+v)}
            min={1}
            max={50}
            step={1}
          />
        </PohCol>
        <PohCol sm={4}>
          <PohInput
            label="Вместимость (экстрим)"
            type={InputTypes.number}
            min={1}
            max={50}
            step={1}
            required
            value={modelData.capacity_max ? modelData.capacity_max.toString() : ''}
            onChange={(v) => handleChange('capacity_max')(+v)}
          />
        </PohCol>
      </PohRow>

      <PohInput
        horizontal
        type={InputTypes.textarea}
        label="Комментарий"
        value={modelData.comment}
        onChange={handleChange('comment')}
      />

      <PohRow>
        <PohCol sm={2}></PohCol>
        <PohCol sm={10}>
          <PohButton type="submit" variant={ButtonVariant.Primary}>
            Сохранить
          </PohButton>
        </PohCol>
      </PohRow>
    </form>
  );
};

export default HikingJointlyEquipmentForm;

export const editHikingJointlyEquipmentFormInModal = (
  jointlyEquipment: IHikingJointlyEquipment,
): Promise<IHikingJointlyEquipment> => {
  return new Promise((res) => {
    showModal({
      title:
        jointlyEquipment.id > 0
          ? 'Редактирование ' +
            getHikingJointlyEquipmentNameByType(jointlyEquipment.type).toLowerCase()
          : 'Добавление ' +
            getHikingJointlyEquipmentNameByType(jointlyEquipment.type).toLowerCase(),
      children: (clos) => {
        return (
          <HikingJointlyEquipmentForm
            jointlyEquipment={jointlyEquipment}
            onSave={(up) => {
              res(up);
              clos();
            }}
          />
        );
      },
    });
  });
};
